<?php
declare(strict_types=1);
require_once __DIR__.'/transactions.php';
$offset=0; echo "Telegram polling started\n";
while(true){
 try {
  $res=telegram('getUpdates',['offset'=>$offset,'timeout'=>25,'allowed_updates'=>['message','callback_query']]);
  foreach($res['result']??[] as $u){$offset=max($offset,(int)$u['update_id']+1);$pdo=db();$check=$pdo->prepare('INSERT OR IGNORE INTO telegram_updates(update_id) VALUES(?)');$check->execute([(int)$u['update_id']]);if($check->rowCount()===0)continue;
   if(isset($u['callback_query'])){ $cb=$u['callback_query'];$from=(string)$cb['from']['id'];$data=$cb['data']??'';try{if(!isAdmin($from))throw new RuntimeException('Hanya admin yang dapat menyetujui.');if(preg_match('/^(deposit_approve|deposit_reject):(\d+)$/',$data,$m)){ $id=(int)$m[2];$pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM deposits WHERE id=? AND status='PENDING'");$q->execute([$id]);$d=$q->fetch();if(!$d)throw new RuntimeException('Deposit sudah diproses atau tidak ditemukan.');$new=$m[1]==='deposit_approve'?'APPROVED':'REJECTED';$up=$pdo->prepare('UPDATE deposits SET status=?,approved_by=?,approved_at=CURRENT_TIMESTAMP WHERE id=?');$up->execute([$new,$from,$id]);if($new==='APPROVED'){ $w=$pdo->prepare('SELECT balance FROM wallets WHERE member_id=?');$w->execute([$d['member_id']]);$before=(int)$w->fetchColumn();$after=$before+(int)$d['amount'];$wu=$pdo->prepare('UPDATE wallets SET balance=?,updated_at=CURRENT_TIMESTAMP WHERE member_id=?');$wu->execute([$after,$d['member_id']]);$l=$pdo->prepare("INSERT INTO wallet_ledger(member_id,reference_id,type,amount,balance_before,balance_after,description) VALUES(?,?,'credit',?,?,?,'Deposit disetujui admin')");$l->execute([$d['member_id'],$d['deposit_code'],$d['amount'],$before,$after]);}$pdo->commit();$member=$pdo->prepare('SELECT telegram_id FROM members WHERE id=?');$member->execute([$d['member_id']]);sendText($member->fetchColumn(),"Deposit {$d['deposit_code']} {$new}." );telegram('answerCallbackQuery',['callback_query_id'=>$cb['id'],'text'=>$new]);} }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();telegram('answerCallbackQuery',['callback_query_id'=>$cb['id'],'text'=>$e->getMessage(),'show_alert'=>true]);}continue; }
   if(!isset($u['message']['text']))continue;$msg=$u['message'];$from=(string)$msg['from']['id'];$chat=(string)$msg['chat']['id'];$text=trim($msg['text']);$name=trim(($msg['from']['first_name']??'').' '.($msg['from']['last_name']??''));$username=$msg['from']['username']??null;
   try{
    if(str_starts_with($text,'/start')){ $q=$pdo->prepare('SELECT * FROM members WHERE telegram_id=?');$q->execute([$from]);$m=$q->fetch();if(!$m){$code='MB'.str_pad((string)((int)$pdo->query('SELECT COUNT(*) FROM members')->fetchColumn()+1),6,'0',STR_PAD_LEFT);$pdo->beginTransaction();$i=$pdo->prepare("INSERT INTO members(member_code,telegram_id,username,full_name,role,status) VALUES(?,?,?,?, 'member','active')");$i->execute([$code,$from,$username,$name?:'Telegram Member']);$mid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO wallets(member_id,balance) VALUES(?,0)')->execute([$mid]);$pdo->commit();$m=['member_code'=>$code];}sendText($chat,"<b>Selamat datang di OkeConnect Internal</b>\nID Member: <code>{$m['member_code']}</code>\nPendaftaran otomatis berhasil. Transaksi hanya diproses operator.");}
    elseif($text==='/saldo'){ $q=$pdo->prepare('SELECT m.id,m.member_code,w.balance FROM members m JOIN wallets w ON w.member_id=m.id WHERE m.telegram_id=? AND m.status=\'active\'');$q->execute([$from]);$m=$q->fetch();if(!$m)throw new RuntimeException('Akun tidak aktif.');sendText($chat,"Member: {$m['member_code']}\nSaldo: <b>".money((int)$m['balance'])."</b>");}
    elseif($text==='/admin'){if(!isOperator($from))throw new RuntimeException('Akses operator ditolak.');$counts=$pdo->query("SELECT status,COUNT(*) c FROM transactions GROUP BY status")->fetchAll();$out="<b>PANEL OPERASIONAL</b>\n";foreach($counts as $c)$out.=$c['status'].': '.$c['c']."\n";sendText($chat,$out."\nPerintah: /order KODEPRODUK NOMOR MEMBERID [NOMINAL]");}
    elseif(str_starts_with($text,'/order')){if(!isOperator($from))throw new RuntimeException('Hanya operator yang dapat membuat transaksi.');$p=preg_split('/\\s+/', $text);if(count($p)<4)throw new RuntimeException('Format: /order KODEPRODUK NOMOR MEMBERID [NOMINAL]');$ref=operatorCreateOrder($from,$p[3],$p[1],$p[2],isset($p[4])?(int)$p[4]:0);sendText($chat,"Pesanan tercatat. Ref: <code>{$ref}</code>. Status awal tersimpan; periksa /status {$ref}");}
    elseif(str_starts_with($text,'/status ')){if(!isOperator($from))throw new RuntimeException('Akses operator ditolak.');$ref=trim(substr($text,8));$q=$pdo->prepare('SELECT * FROM transactions WHERE reference_id=?');$q->execute([$ref]);$t=$q->fetch();if(!$t)throw new RuntimeException('Transaksi tidak ditemukan.');sendText($chat,"Ref: <code>{$ref}</code>\nStatus: <b>{$t['status']}</b>\nProduk: {$t['product_code']}\nTujuan: {$t['destination']}\nHarga: ".money((int)$t['selling_price']));}
    elseif(str_starts_with($text,'/recheck ')){if(!isOperator($from))throw new RuntimeException('Akses operator ditolak.');$ref=trim(substr($text,9));$q=$pdo->prepare('SELECT * FROM transactions WHERE reference_id=?');$q->execute([$ref]);$t=$q->fetch();if(!$t)throw new RuntimeException('Transaksi tidak ditemukan.');if(in_array($t['status'],['SUCCESS','FAILED'],true))throw new RuntimeException('Transaksi sudah final: '.$t['status']);$st=oke()->checkStatus($t['product_code'],$t['destination'],$ref);$status=$st->isSuccessful()?'SUCCESS':($st->isFailed()?'FAILED':($st->isPending()?'PROCESS':'PROCESS'));finalizeTransaction($ref,$status,$st->serialNumber??null,$st->failureReason??null,$st->transactionId??null);sendText($chat,"Pemeriksaan selesai: <code>{$ref}</code> → <b>{$status}</b>");}
    else sendText($chat,"Perintah tersedia: /start, /saldo, /admin");
   }catch(Throwable $e){sendText($chat,'Gagal: '.htmlspecialchars($e->getMessage()));}
  }
 }catch(Throwable $e){file_put_contents(dirname(__DIR__).'/logs/bot.log',date('c').' '.$e->getMessage()."\n",FILE_APPEND);sleep(3);}
}
